# ══════════════════════════════════════════════════════════════════════════════
# LOAD PACKAGE
# ══════════════════════════════════════════════════════════════════════════════
# Load the package from next to this script so it works both locally and when
# deployed (Streamlit Cloud, Linux). GradBoost_package.pkl must sit in the repo.
PKG_PATH = Path(__file__).parent / "GradBoost_package.pkl"

@st.cache_resource(show_spinner="Loading model…")
def load_package(path):
    return joblib.load(path)

try:
    pkg = load_package(PKG_PATH)
except FileNotFoundError:
    st.error(f"**Package not found:** `{PKG_PATH}` — run `Package.py` first.")
    st.stop()

model             = pkg['model']
TARGET            = pkg.get('target', 'H2O2 conc. (mg/L)')
feature_names     = pkg['feature_names']
categorical_cols  = pkg['categorical_cols']
numerical_cols    = pkg['numerical_cols']
cat_values        = pkg['cat_values']
num_stats         = pkg.get('num_stats', {})
cv_results        = pkg['cv_results']
train_metrics_f   = pkg['train_metrics_final']
test_metrics_f    = pkg['test_metrics_final']
oof_preds         = pkg['oof_preds']
oof_actuals       = pkg['oof_actuals']
y_train_arr       = pkg['y_train']
train_preds_final = pkg['train_preds_final']
y_test_arr        = pkg['y_test']
test_preds_final  = pkg['test_preds_final']
feat_importances  = pkg['feat_importances']

UNIT = "mg/L"

# ── Thermal handling ────────────────────────────────────────────────────────
# 'Is_thermal' is no longer shown; it is derived from the 'Modification' choice.
# 'Thermal_temperature' sits under 'Modification' and is only enabled when the
# modification is thermal.
THERMAL_MOD  = 'Thermal'          # value of 'Modification' that enables temperature
HIDDEN_FEATS = {'Is_thermal'}     # required by the model, but not shown as an input

# ── Feature groupings (by name; anything left over is collected automatically) ──
GROUP_DEFS = [
    ("① Electrode Configuration",
     ['Anode', 'Cathode', 'Effective size (cm2)', 'Spacing (cm)',
      'Modification', 'Thermal_temperature']),
    ("② Catalyst & Binder",
     ['Cathode Catalyst', 'Binder', 'Binder amount (mL)']),
    ("③ Reactor & Hydraulics",
     ['Reactor type', 'Reactor volume (mL)', 'Flow rate (mL/min)', 'Stirring speed (rpm)']),
    ("④ Electrolyte & Operation",
     ['Electrolyte', 'Electrolyte Conc.(mM)', 'Initial pH', 'Current density (mA)',
      'Reaction time (min)', 'Reusability']),
]

# keep only features that exist and are not hidden, then sweep up any that were missed
GROUPS, _seen = [], set()
for title, feats in GROUP_DEFS:
    present = [f for f in feats if f in feature_names and f not in HIDDEN_FEATS]
    if present:
        GROUPS.append((title, present))
        _seen.update(present)
_leftover = [f for f in feature_names if f not in _seen and f not in HIDDEN_FEATS]
if _leftover:
    GROUPS.append(("⑤ Other Parameters", _leftover))

BINARY_COLS = set()   # no binary inputs shown


def num_default(feat):
    s = num_stats.get(feat)
    return round(float(s['median']), 4) if s else 0.0


def num_range(feat):
    s = num_stats.get(feat)
    if s:
        return float(s['min']), float(s['max'])
    return 0.0, 100.0

# ══════════════════════════════════════════════════════════════════════════════
# JOURNAL-STYLE PLOTLY THEME
# ══════════════════════════════════════════════════════════════════════════════
def journal_layout(fig, xtitle="", ytitle="", height=560, square=False):
    axis = dict(
        showline=True, linecolor=INK, linewidth=1.1, mirror=True,
        ticks="outside", tickcolor=INK, ticklen=5, tickwidth=1.1,
        showgrid=False, zeroline=False,
        title_font=dict(size=14, family="Inter", color=INK),
        tickfont=dict(size=12, family="Inter", color=INK),
    )
    fig.update_layout(
        font=dict(family="Inter", color=INK, size=12),
        plot_bgcolor="white", paper_bgcolor="white",
        height=height,
        margin=dict(l=70, r=28, t=24, b=64),
        xaxis={**axis, "title": xtitle},
        yaxis={**axis, "title": ytitle},
        legend=dict(
            orientation="h", yanchor="bottom", y=1.01, xanchor="left", x=0,
            bgcolor="rgba(0,0,0,0)", font=dict(size=12, family="Inter", color=INK),
        ),
    )
    if square:
        fig.update_yaxes(scaleanchor="x", scaleratio=1)
    return fig

# ══════════════════════════════════════════════════════════════════════════════
# SIDEBAR
# ══════════════════════════════════════════════════════════════════════════════
with st.sidebar:
    st.markdown("### Model Card")
    st.markdown('<div class="sb-k">Estimator</div>'
                '<div class="sb-v">Gradient Boosting Regressor</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="sb-k">Response</div>'
                f'<div class="sb-v">H₂O₂ concentration ({UNIT})</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="sb-k">Predictors</div>'
                f'<div class="sb-v">{len(feature_names)} features</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="sb-k">Validation</div>'
                f'<div class="sb-v">5-fold CV · held-out test</div>', unsafe_allow_html=True)
    st.markdown("---")

    # Performance summary
    st.markdown("### Predictive Error")
    rmse_v  = cv_results['RMSE']['val_mean']
    rmse_vs = cv_results['RMSE']['val_std']
    r2_v    = cv_results['R2']['val_mean']
    r2_vs   = cv_results['R2']['val_std']
    st.markdown(f'<div class="sb-k">RMSE — cross-validation</div>'
                f'<div class="sb-v">{rmse_v:.2f} ± {rmse_vs:.2f} {UNIT}</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="sb-k">RMSE — test</div>'
                f'<div class="sb-v">{test_metrics_f["RMSE"]:.2f} {UNIT}</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="sb-k">R² — cross-validation</div>'
                f'<div class="sb-v">{r2_v:.3f} ± {r2_vs:.3f}</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="sb-k">R² — test</div>'
                f'<div class="sb-v">{test_metrics_f["R2"]:.3f}</div>', unsafe_allow_html=True)
    st.markdown("---")

    if st.button("Generate random specimen", key="rand_btn"):
        for f in feature_names:
            if f in BINARY_COLS:
                st.session_state[f'inp_{f}'] = random.choice([0, 1])
            elif f in categorical_cols:
                st.session_state[f'inp_{f}'] = random.choice(cat_values[f])
            else:
                lo, hi = num_range(f)
                st.session_state[f'inp_{f}'] = round(random.uniform(lo, hi), 4)
        st.rerun()

