# MASTHEAD
# ══════════════════════════════════════════════════════════════════════════════
st.markdown(
    '<div class="masthead">'
    '<div class="eyebrow">Electrochemical Hydrogen Peroxide Production</div>'
    '<h1 class="page-title">Data-Driven Prediction of H₂O₂ Concentration</h1>'
    '</div>'
    '<p class="page-subtitle">A gradient-boosted regression model relating reactor '
    'configuration, electrode chemistry, and operating conditions to the equilibrium '
    'hydrogen-peroxide concentration. Specify the experimental parameters below to obtain '
    'a model-predicted response.</p>',
    unsafe_allow_html=True
)
st.markdown("<br>", unsafe_allow_html=True)

# ══════════════════════════════════════════════════════════════════════════════
# INPUT FORM
# ══════════════════════════════════════════════════════════════════════════════
input_vals = {}
# lay the groups across two rows of columns for a balanced, minimal grid
row1 = GROUPS[:3]
row2 = GROUPS[3:]

def render_group(container, title, feats):
    with container:
        st.markdown(f'<div class="card"><div class="card-title"><span>▪</span>{title}</div>',
                    unsafe_allow_html=True)
        for feat in feats:
            if feat in BINARY_COLS:
                cur = int(st.session_state.get(f'inp_{feat}', 0) or 0)
                choice = st.selectbox(feat.replace('_', ' '), ["No", "Yes"],
                                      index=cur, key=f'sel_{feat}')
                input_vals[feat] = 1 if choice == "Yes" else 0
                st.session_state[f'inp_{feat}'] = input_vals[feat]
            elif feat in categorical_cols:
                opts = cat_values[feat]
                cur = st.session_state.get(f'inp_{feat}', opts[0])
                idx = opts.index(cur) if cur in opts else 0
                val = st.selectbox(feat, opts, index=idx, key=f'inp_{feat}')
                input_vals[feat] = val
            elif feat == 'Thermal_temperature':
                # Enabled only when Modification is thermal; greyed out otherwise.
                label = feat.replace('_', ' ')      # -> "Thermal temperature"
                thermal_on = input_vals.get(
                    'Modification', st.session_state.get('inp_Modification')) == THERMAL_MOD
                if thermal_on:
                    val = st.number_input(
                        label,
                        value=float(st.session_state.get(f'inp_{feat}', num_default(feat))),
                        format="%.4f", key=f'inp_{feat}'
                    )
                    input_vals[feat] = val
                else:
                    st.number_input(
                        label, value=0.0, format="%.4f",
                        key=f'inp_{feat}_disabled', disabled=True,
                        help=f"Enabled only when Modification is set to “{THERMAL_MOD}”."
                    )
                    input_vals[feat] = 0.0
            else:
                val = st.number_input(
                    feat,
                    value=float(st.session_state.get(f'inp_{feat}', num_default(feat))),
                    format="%.4f", key=f'inp_{feat}'
                )
                input_vals[feat] = val
        st.markdown('</div>', unsafe_allow_html=True)

cols1 = st.columns(len(row1))
for c, (title, feats) in zip(cols1, row1):
    render_group(c, title, feats)

if row2:
    cols2 = st.columns(len(row2) if len(row2) > 1 else 2)
    for c, (title, feats) in zip(cols2, row2):
        render_group(c, title, feats)

# Derive the hidden 'Is_thermal' feature from the Modification choice
if 'Is_thermal' in feature_names:
    input_vals['Is_thermal'] = 1 if input_vals.get('Modification') == THERMAL_MOD else 0

# ══════════════════════════════════════════════════════════════════════════════
# PREDICT
# ══════════════════════════════════════════════════════════════════════════════
st.markdown("<br>", unsafe_allow_html=True)
_, btn_col, _ = st.columns([1.2, 1.6, 1.2])
with btn_col:
    predict_clicked = st.button(f"Predict H₂O₂ concentration", key="predict_btn")

if predict_clicked:
    numeric_vals = [v for k, v in input_vals.items()
                    if k not in categorical_cols and isinstance(v, (int, float))]
    if any(v < 0 for v in numeric_vals):
        st.error("All numeric inputs must be ≥ 0.")
    else:
        try:
            row = pd.DataFrame([input_vals])[feature_names]
            pred = float(model.predict(row)[0])
            pred = max(pred, 0.0)
            _, res_col, _ = st.columns([1, 2, 1])
            with res_col:
                st.markdown(
                    f"""
                    <div class="result-box">
                        <div class="result-label">Predicted H₂O₂ Concentration</div>
                        <div class="result-value">{pred:,.2f}</div>
                        <div class="result-unit">{UNIT}</div>
                        <div class="result-sub">Gradient Boosting · 5-fold cross-validated ·
                        leakage-free pipeline encoding</div>
                    </div>
                    """,
                    unsafe_allow_html=True,
                )
        except Exception as ex:
            st.error(f"Prediction failed: {ex}")
            st.exception(ex)

# ══════════════════════════════════════════════════════════════════════════════
# FIGURES
# ══════════════════════════════════════════════════════════════════════════════
st.markdown("<br>", unsafe_allow_html=True)

mask = ~np.isnan(oof_preds)

# ── Parity (Observed vs Predicted) ────────────────────────────────────────────
st.markdown("#### Parity Plot")
fig = go.Figure()
lim = max(float(np.nanmax(y_train_arr)), float(np.nanmax(y_test_arr)),
          float(np.nanmax(train_preds_final)), float(np.nanmax(test_preds_final))) * 1.05

fig.add_trace(go.Scatter(
    x=[0, lim], y=[0, lim], mode='lines',
    line=dict(color=INK, dash='dash', width=1.1),
    name='1 : 1 line', hoverinfo='skip'))
fig.add_trace(go.Scatter(
    x=y_train_arr, y=train_preds_final, mode='markers', name='Training',
    marker=dict(color=C_TRAIN, size=6, opacity=0.75,
                line=dict(color='white', width=0.4))))
fig.add_trace(go.Scatter(
    x=oof_actuals[mask], y=oof_preds[mask], mode='markers', name='Cross-validation',
    marker=dict(color=C_VAL, size=6, opacity=0.65,
                line=dict(color='white', width=0.4))))
fig.add_trace(go.Scatter(
    x=y_test_arr, y=test_preds_final, mode='markers', name='Test',
    marker=dict(color=C_TEST, size=8, opacity=0.9,
                line=dict(color='white', width=0.6))))

journal_layout(fig,
               xtitle=f"Observed H₂O₂ ({UNIT})",
               ytitle=f"Predicted H₂O₂ ({UNIT})",
               height=600, square=True)
fig.update_xaxes(range=[0, lim], constrain='domain')
fig.update_yaxes(range=[0, lim], constrain='domain')
st.plotly_chart(fig, use_container_width=True)
st.markdown(
    f"<p style='font-size:12.5px;color:{MUTED};margin-top:-6px;'>"
    "<b>Figure 1.</b> Observed versus predicted H₂O₂ concentration for the training, "
    "cross-validation (out-of-fold), and held-out test partitions. The dashed line "
    "denotes perfect agreement.</p>", unsafe_allow_html=True)

